import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("a single sword → base premium 100 G (+10 % first insurance +5 G fee = 115 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("a single amulet → base premium 60 G (+10 % first insurance +5 G fee = 71 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("a single staff → base premium 80 G (+10 % first insurance +5 G fee = 93 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it.todo("a single potion → base premium 40 G");
    it.todo("a single rune (component) → base premium 25 G");
    it.todo("a single moonstone (component) → base premium 25 G");
    it.todo("a sword and an amulet → policy base premium 160 G");
  });

  describe("quote — component blocks", () => {
    it.todo("2 runes → 50 G base premium (no block)");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium (no block)");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-scoped modifiers", () => {
    it.todo("a cursed sword adds a 50 % risk surcharge → 100 + 50 G");
    it.todo("a sword with enchantment 5 adds a 30 % surcharge → 100 + 30 G");
    it.todo("a sword with enchantment 4 gets no high-enchantment surcharge");
    it.todo("a cursed sword with enchantment 5 gets both surcharges → 100 + 50 + 30 G");
    it.todo(
      "cursed surcharge applies to the cursed item only: cursed sword + plain amulet → 160 base + 50 curse = 210 G before further modifiers and fee",
    );
  });

  describe("quote — policy-scoped modifiers", () => {
    it.todo("a customer with 2 years with MHPCO receives the 20 % loyalty discount");
    it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
    it.todo("a first insurance carries a 10 % initial assessment surcharge");
    it.todo("the second contract in a scenario receives a 15 % follow-up discount");
    it.todo("the first insurance surcharge still applies on a follow-up contract");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("quote — rounding in the MHPCO's favour", () => {
    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)",
    );
    it.todo("a damage amount below the deductible does not produce a negative payout");
  });

  describe("claim — cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only)");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 G then 600 G, remaining cap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries against two insured swords → each gets its own deductible");
    it.todo("more damage entries of a type than insured → the claim is rejected");
  });

  describe("claim — rounding in the MHPCO's favour", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("errors", () => {
    it.todo("a quote with an unknown item type (broomstick) → rejected with an error description");
    it.todo("a claim damaging an amulet when only a sword is insured → rejected");
    it.todo("a claim damaging an item with an unknown type → rejected");
    it.todo("a claim with a damage entry of amount -200 → rejected");
  });
});

