export type Item = {
  type: string;
};

export type Step = {
  op: "quote";
  items: Item[];
};

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type QuoteResult = {
  premium: number;
};

export type ScenarioResult = {
  results: QuoteResult[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// A block is exactly BLOCK_SIZE alike items, charged as one unit.
const formsBlock = (count: number): boolean => count === BLOCK_SIZE;

const groupBasePremium = (type: string, count: number): number =>
  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + groupBasePremium(type, count),
    0,
  );

// The MHPCO rounds in its own favour: premiums up, payouts down.
const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);

const quote = (step: Step): QuoteResult => {
  const basePremium = policyBasePremium(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const modifiedPremium = basePremium + firstInsuranceSurcharge;

  return {
    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
  };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(quote),
});

