export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type ClaimStep = {
  op: "claim";
  policy: number;
  incident: Incident;
};

export type Step = QuoteStep | ClaimStep;

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type QuoteResult = {
  premium: number;
};

export type ClaimResult = {
  payout: number;
  remainingCap: number;
};

export type StepResult = QuoteResult | ClaimResult;

export type ScenarioResult = {
  results: StepResult[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
const CAP_MULTIPLIER = 2;

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];

const itemBasePremium = (item: Item): number => basePremiumForType(item.type);

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// A block is exactly BLOCK_SIZE alike items, charged as one unit.
const formsBlock = (count: number): boolean => count === BLOCK_SIZE;

const groupBasePremium = (type: string, count: number): number =>
  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + groupBasePremium(type, count),
    0,
  );

// The MHPCO rounds in its own favour: premiums up, payouts down.
const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);

// Item-scoped surcharge clauses. Each applies, independently and additively,
// to the affected item's own base premium.
const ITEM_SURCHARGE_CLAUSES: {
  applies: (item: Item) => boolean;
  rate: number;
}[] = [
  {
    applies: (item) => item.cursed === true,
    rate: CURSE_SURCHARGE_RATE,
  },
  {
    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
  },
];

const itemSurcharge = (item: Item): number => {
  const base = itemBasePremium(item);

  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
    (total, clause) => total + base * clause.rate,
    0,
  );
};

const itemSurcharges = (items: Item[]): number =>
  items.reduce((total, item) => total + itemSurcharge(item), 0);

// Everything a policy-scoped clause may inspect.
type Policy = {
  items: Item[];
  customer: Customer;
  isFollowUpContract: boolean;
};

// Policy-scoped modifier clauses. Each applies, independently and additively,
// to the policy base premium. A negative rate is a discount.
const POLICY_MODIFIER_CLAUSES: {
  applies: (policy: Policy) => boolean;
  rate: number;
}[] = [
  {
    applies: () => true,
    rate: FIRST_INSURANCE_SURCHARGE_RATE,
  },
  {
    applies: (policy) =>
      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
    rate: -LOYALTY_DISCOUNT_RATE,
  },
  {
    applies: (policy) => policy.isFollowUpContract,
    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
  },
];

const policyModifiers = (policy: Policy, policyBase: number): number =>
  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
    (total, clause) => total + policyBase * clause.rate,
    0,
  );

const quote = (policy: Policy): QuoteResult => {
  const policyBase = policyBasePremium(policy.items);
  const modifiedPremium =
    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);

  return {
    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
  };
};

const insuranceSum = (items: Item[]): number =>
  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);

// A policy issued by a quote step, tracked so later claims can draw on its cap.
type IssuedPolicy = {
  items: Item[];
  remainingCap: number;
};

// The cap a fresh policy starts with: a multiple of the insured items' value,
// independent of any premium modifiers.
const issuePolicy = (items: Item[]): IssuedPolicy => ({
  items,
  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
});

// Reimbursement clauses read the damaged item, so a claim resolves each
// damage entry back to the insured item it refers to.
const reimbursedAmount = (item: Item, amount: number): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : amount;

// Each damaged item carries its own deductible.
const payoutForIncident = (incident: Incident, items: Item[]): number =>
  incident.damages.reduce((total, damage) => {
    const item = items.find((candidate) => candidate.type === damage.itemType)!;

    return total + reimbursedAmount(item, damage.amount) - DEDUCTIBLE_PER_DAMAGE;
  }, 0);

// A claim draws its payout down from the policy's remaining cap, so the
// policy carries less cover into any later claim against it.
const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
  ...policy,
  remainingCap: policy.remainingCap - payout,
});

export const runScenario = (scenario: Scenario): ScenarioResult => {
  let hasIssuedContract = false;
  const policies = new Map<number, IssuedPolicy>();

  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      const payout = payoutForIncident(step.incident);
      const policy = drawDownCap(policies.get(step.policy)!, payout);
      policies.set(step.policy, policy);

      return { payout, remainingCap: policy.remainingCap };
    }

    policies.set(index, issuePolicy(step.items));

    const result = quote({
      items: step.items,
      customer: scenario.customer,
      isFollowUpContract: hasIssuedContract,
    });
    hasIssuedContract = true;

    return result;
  });

  return { results };
};

