// Each damage entry is settled against a distinct insured item, so a claim
// cannot draw on the same item twice. Removes the matched item from `unclaimed`.
const takeInsuredItemFor = (damage: Damage, unclaimed: Item[]): Item => {
  const index = unclaimed.findIndex((item) => item.type === damage.itemType);
  if (index === -1) {
    throw new Error(
      `the policy does not cover a further ${damage.itemType} to claim against`,
    );
  }

  return unclaimed.splice(index, 1)[0];
};

