import { describe, it, expect } from "vitest";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";

const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));

type CliRun = { stdout: string; stderr: string; code: number };

// The CLI is exercised as a real subprocess so that stdin, stdout and the
// exit code — the whole of its contract — are genuinely under test.
const runCli = (input: string): Promise<CliRun> =>
  new Promise((resolve, reject) => {
    const child = spawn("npx", ["tsx", CLI], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";

    child.stdout.on("data", (chunk) => (stdout += chunk));
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.on("error", reject);
    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));

    child.stdin.end(input);
  });

describe("claim-office CLI", () => {
  it(
    "reads a scenario from stdin and writes {results: [...]} to stdout",
    async () => {
      const scenario = {
        customer: { yearsWithMHPCO: 5 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "amulet", material: "silver", enchantment: 2, cursed: false },
            ],
          },
          {
            op: "claim",
            policy: 0,
            incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
          },
        ],
      };

      const { stdout, code } = await runCli(JSON.stringify(scenario));

      expect(code).toBe(0);
      expect(JSON.parse(stdout)).toEqual({
        results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
      });
    },
    30000,
  );

  it.todo("writes one result per step, in the same order as the input steps");
  it.todo("writes {premium} for a quote step and {payout, remainingCap} for a claim step");
  it.todo("exits with a non-zero status and writes to stderr on an unknown item type");
  it.todo("exits with a non-zero status and writes to stderr on an invalid claim");
  it.todo("writes no results to stdout when the scenario is rejected");
});

